function restoreTimerSession(){try{const saved=JSON.parse(storageRead(TIMER_SESSION_KEY)||'null');if(!saved)return;restoredFocusTaskId=saved.taskId||'';focusSessionId=saved.id||'';state.focus={minutes:saved.minutes||25,mode:saved.mode==='break'?'break':'focus'};if(saved.status==='running'&&saved.deadline){timerDeadline=Number(saved.deadline);focusSeconds=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));lastChimeMinute=Math.ceil(focusSeconds/60);timerRunning=true;expiredTimerSession=focusSeconds===0}else{focusSeconds=Math.max(0,Number(saved.remaining)||0);timerRunning=false}}catch{storageDelete(TIMER_SESSION_KEY)}}
function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function shiftDate(date,days){const d=new Date(date);d.setDate(d.getDate()+days);return d}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message,kind='success',action=null){const node=document.createElement('div');node.className=`toast toast-${kind}`;const icon=document.createElement('i');icon.className=`fa-solid ${kind==='error'?'fa-circle-exclamation':'fa-circle-check'}`;const text=document.createElement('span');text.textContent=message;node.append(icon,text);if(action){const button=document.createElement('button');button.type='button';button.className='toast-action';button.textContent=action.label;button.addEventListener('click',()=>{action.run();node.remove()},{once:true});node.append(button)}$('toastRegion').append(node);if(kind==='error')playSfx('error');setTimeout(()=>{node.classList.add('toast-leaving');setTimeout(()=>node.remove(),220)},action?6000:3300)}
function syncStatus(kind,label){$('syncDot').className=`sync-dot ${kind==='ready'?'':kind}`;$('syncLabel').textContent=label}
function levelInfo(){let rank=RANKS[0];for(const r of RANKS)if(state.xp>=r.xp)rank=r;return {rank,next:RANKS.find(r=>r.level===rank.level+1)||null}}
function completedToday(){return state.activity[dayKey()]||0}
function weekKey(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()+3-(x.getDay()+6)%7);const w=new Date(x.getFullYear(),0,4);return `${x.getFullYear()}-W${String(1+Math.round(((x-w)/86400000-3+(w.getDay()+6)%7)/7)).padStart(2,'0')}`}
function bountyClaimed(){return !!state.bounties[dayKey()]?.claimed}
function currentStreak(){let date=new Date();let key=dayKey(date);if(!(state.activity[key]>0)&&!state.shieldedDays.includes(key))date=shiftDate(date,-1);let streak=0;while((state.activity[dayKey(date)]||0)>0||state.shieldedDays.includes(dayKey(date))){streak++;date=shiftDate(date,-1)}return streak}
function applyDailyRules(){const today=dayKey();const prev=dayKey(shiftDate(new Date(),-1));if(state.activity[prev]>0&&state.activity[today]===undefined&&state.streakShield&&state.shieldUsedOn!==today){state.activity[today]=0;state.shieldedDays.push(today);state.streakShield=false;state.shieldUsedOn=today;persist();toast('Your streak shield protected your streak overnight.')}const wk=weekKey();if(state.bossWeek!==wk){state.bossWeek=wk;state.bossHp=500}if(state.bossAttackDay!==today&&state.tasks.some(t=>!t.completed)){state.petEnergy=Math.max(0,state.petEnergy-3);state.bossAttackDay=today}const dayDiff=Math.floor((Date.now()-(state.lastDecay||Date.now()))/86400000);if(dayDiff>0){state.petEnergy=Math.max(0,state.petEnergy-Math.min(60,dayDiff*5));state.lastDecay=Date.now()}}
