function renderUpcoming(){const wrap=$('upcomingList');wrap.replaceChildren();const pending=state.tasks.filter(t=>!t.completed);const due=pending.filter(t=>t.due).sort((a,b)=>a.due.localeCompare(b.due));const items=(due.length?due:pending).slice(0,3);if(!items.length){const empty=document.createElement('div');empty.className='upcoming-empty';empty.textContent='You’re all caught up. Add a quest and it will show up here.';wrap.append(empty);return}items.forEach(t=>{const row=document.createElement('div');row.className='upcoming-item';const date=document.createElement('span');date.className=`upcoming-date ${t.due===dayKey()?'today':''}`;if(t.due){const d=new Date(`${t.due}T12:00:00`);date.textContent=t.due===dayKey()?'TODAY':new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(d)}else date.innerHTML='<i class="fa-solid fa-list-check"></i>';const body=document.createElement('div'),title=document.createElement('div'),meta=document.createElement('div'),dot=document.createElement('span');title.className='upcoming-title';title.textContent=t.text;meta.className='upcoming-meta';meta.textContent=t.due?`${CATEGORIES[t.category]||'Quest'} · ${t.due<dayKey()?'Overdue':'Due date'}`:`${CATEGORIES[t.category]||'Quest'} · No due date`;dot.className=`upcoming-priority ${t.priority||'low'}`;body.append(title,meta);row.append(date,body,dot);row.title='Open this quest on the board';row.addEventListener('click',()=>{const input=$('searchInput');input.value=t.text;filter='all';document.querySelectorAll('.board-tab').forEach(b=>{const selected=b.dataset.filter==='all';b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});renderTasks();$('quests').scrollIntoView({behavior:'smooth',block:'start'})});wrap.append(row)})}
function renderHeatmap(){const days=analyticsRange==='month'?30:365;const container=$('heatmap');container.replaceChildren();const start=shiftDate(new Date(),-(days-1));start.setDate(start.getDate()-((start.getDay()+6)%7));const actualStart=analyticsRange==='month'?shiftDate(new Date(),-29):shiftDate(new Date(),-364);const months=[];for(let i=0;i<days;i++){const date=shiftDate(actualStart,i),key=dayKey(date),n=state.activity[key]||0;const c=document.createElement('span');c.className='heat-cell';const intensity=n===0?0:n===1?1:n<=3?2:n<=5?3:4;c.classList.add(`heat-${intensity}`);c.title=`${key}: ${n} completed`;container.append(c);if(date.getDate()===1||i===0)months.push({index:i,label:new Intl.DateTimeFormat(undefined,{month:'short'}).format(date)})}const monthsEl=$('heatmapMonths');monthsEl.replaceChildren();for(const m of months){const span=document.createElement('span');span.textContent=m.label;monthsEl.append(span)}const total=Object.entries(state.activity).filter(([d])=>d>=dayKey(shiftDate(new Date(),-days+1))).reduce((sum,[,n])=>sum+n,0);$('activitySummary').textContent=`${total} quests completed in the last ${analyticsRange==='month'?'30 days':'year'}`}
