function dayOffset(iso){if(!iso)return null;const target=new Date(iso+'T00:00:00'),today=new Date();today.setHours(0,0,0,0);return Math.round((target-today)/86400000)}
function dueDescription(iso){const n=dayOffset(iso);if(n===null)return '';if(n<0)return 'Overdue · '+Math.abs(n)+'d';if(n===0)return 'Due today';if(n===1)return 'Due tomorrow';return 'Due in '+n+'d'}
function showShop(){playSfx('tap');const content=document.createElement('div');content.innerHTML=`<div class="section-kicker">YOUR REWARD STORE</div><h2 id="modalTitle">Shop</h2><p>Spend your <strong style="color:var(--accent)">${state.gold||0} gold</strong> on workspace looks and companion care.</p><div class="section-kicker shop-subhead">THEMES</div>`;THEMES.forEach(t=>{const row=document.createElement('div');row.className='theme-option';row.innerHTML=`<div class="theme-swatch"><div class="swatches">${t.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</div><div><strong>${t.name}</strong><div class="theme-requirement">${t.cost===0?'Available now':`${t.cost} gold · Level ${t.level}`}</div></div></div>`;const unlocked=(state.unlockedThemes||['default']).includes(t.id);const canUnlock=levelInfo().rank.level>=t.level&&(state.gold||0)>=t.cost;const btn=document.createElement('button');btn.textContent=state.theme===t.id?'Equipped':unlocked?'Equip':levelInfo().rank.level<t.level?'Locked':`Unlock · ${t.cost}g`;btn.disabled=state.theme===t.id||(!unlocked&&!canUnlock);btn.addEventListener('click',()=>applyTheme(t.id));row.append(btn);content.append(row)});const supplies=document.createElement('div');supplies.innerHTML='<div class="section-kicker shop-subhead">COMPANION SUPPLIES</div>';[{title:'Tiny treat',detail:'+10 companion energy',price:6,disabled:state.petEnergy>=100,action:()=>{state.gold-=6;state.petEnergy=Math.min(100,state.petEnergy+10);animatePet();playSfx("success");persist();render();showShop();toast("Your companion enjoyed a tiny treat!")}}, {title:'Glowberry snack',detail:'+25 companion energy',price:12,disabled:state.petEnergy>=100,action:()=>{state.gold-=12;state.petEnergy=Math.min(100,state.petEnergy+25);animatePet();playSfx("success");persist();render();showShop();toast("Your companion enjoyed a glowberry snack!")}}, {title:'Starfruit feast',detail:'+50 companion energy',price:22,disabled:state.petEnergy>=100,action:()=>{state.gold-=22;state.petEnergy=Math.min(100,state.petEnergy+50);animatePet();playSfx("bounty");persist();render();showShop();toast("A starfruit feast brought your companion back to life!")}}, {title:'Streak shield recharge',detail:'Restore one missed-day save',price:45,disabled:!!state.streakShield,action:()=>{state.gold-=45;state.streakShield=true;persist();render();showShop();toast("Streak shield recharged.")}}].forEach(item=>{const row=document.createElement('div');row.className='theme-option supply-option';const label=document.createElement('div');label.className='theme-swatch';label.innerHTML=`<div><strong>${item.title}</strong><div class="theme-requirement">${item.detail}</div></div>`;const btn=document.createElement('button');btn.textContent=`${item.price} gold`;btn.disabled=item.disabled||(state.gold||0)<item.price;btn.addEventListener('click',item.action);row.append(label,btn);supplies.append(row)});content.append(supplies);openModal(content)}function openModal(content){$('modalContent').replaceChildren(content);$('modalBackdrop').hidden=false;setTimeout(()=>$('modalClose').focus(),0)}function openModalClose(){const title=$('modalContent').querySelector('#modalTitle')?.textContent||'';if(title.includes('Make your next step feel lighter'))storageWrite('tasksphere.welcome.v1','1');$('modalBackdrop').hidden=true}
function cloudConfigured(){return /^https:\/\/[\w-]+\.supabase\.co$/.test(SUPABASE_URL)&&SUPABASE_ANON_KEY.length>30}
async function initCloud(){if(!cloudConfigured()){syncStatus('ready','Saved on this device');return}if(!window.supabase?.createClient){syncStatus('error','Cloud library unavailable · local copy safe');return}try{supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await supabaseClient.auth.getSession();if(error)throw error;user=data.session?.user||null;if(user)await loadCloud();supabaseClient.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;if(user)queueMicrotask(loadCloud);else syncStatus('ready','Saved on this device')});syncStatus('ready',user?`Synced · ${user.email}`:'Cloud ready · sign in to sync')}catch(error){supabaseClient=null;syncStatus('error','Cloud setup needs attention');const frag=document.createElement('div');frag.innerHTML='<div class="section-kicker">YOUR ACCOUNT</div><h2 id="modalTitle">Account & preferences</h2><p id="authStatus">Local mode is active. Configure Supabase to sync securely across devices.</p><div class="modal-field"><label for="authEmail">Email</label><input id="authEmail" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="modal-field"><label for="authPassword">Password</label><input id="authPassword" type="password" autocomplete="current-password" placeholder="At least 6 characters"></div><div class="modal-row"><button class="primary-btn" id="signInBtn">Sign in</button><button class="secondary-btn" id="signUpBtn" style="margin:0">Create account</button></div><button class="text-btn" id="signOutBtn" style="margin-top:13px;display:none">Sign out</button><hr class="modal-divider"><div class="section-kicker">COMFORT & ACCESSIBILITY</div><div class="modal-field"><label for="focusDefaultSelect">Default focus length</label><select id="focusDefaultSelect"><option value="15">15 minutes</option><option value="25">25 minutes</option><option value="45">45 minutes</option><option value="60">60 minutes</option></select></div><div class="modal-field"><label for="soundVolumeInput">Sound volume <span id="soundVolumeValue"></span></label><input id="soundVolumeInput" type="range" min="0" max="100" step="5"></div><div class="modal-field"><label for="motionSelect">Animation intensity</label><select id="motionSelect"><option value="full">Full</option><option value="subtle">Subtle</option><option value="reduced">Reduced</option></select></div><hr class="modal-divider"><div class="section-kicker">PRESENTATION DEMO</div><p>Sample quests are clearly marked and can be cleared without deleting your own quests.</p><div class="modal-row"><button class="secondary-btn" id="loadDemoBtn" style="margin:0">Load demo quests</button><button class="text-btn" id="resetDemoBtn">Clear demo quests</button></div><p class="setup-note">Cloud sync only activates after you add your Supabase project URL and public anon key in <code>script.js</code> and run <code>supabase.sql</code>. Never use a service role key in this page.</p>';openModal(frag);installSocialAuthButtons();$('authStatus').textContent=user?`Signed in as ${user.email}. Cloud sync is active.`:cloudConfigured()?'Connect your account to sync cloud data.':'Local mode is active. Configure Supabase to sync securely across devices.';$('signOutBtn').style.display=user?'inline-block':'none';$('focusDefaultSelect').value=String(state.focusDefault||25);$('soundVolumeInput').value=Math.round((state.soundVolume??.45)*100);$('soundVolumeValue').textContent=`${$('soundVolumeInput').value}%`;$('motionSelect').value=state.motionLevel||'full';$('signInBtn').addEventListener('click',()=>authAction('signin'));$('signUpBtn').addEventListener('click',()=>authAction('signup'));$('signOutBtn').addEventListener('click',async()=>{await supabaseClient?.auth.signOut();user=null;syncStatus('ready','Saved on this device');openModalClose();toast('Signed out. Your local copy remains available.')});$('focusDefaultSelect').addEventListener('change',e=>{state.focusDefault=Number(e.target.value);if(!timerRunning&&state.focus.mode==='focus'){state.focus={minutes:state.focusDefault,mode:'focus'};focusSeconds=state.focusDefault*60;document.querySelectorAll('.timer-presets button').forEach(x=>x.classList.toggle('selected',Number(x.dataset.minutes)===state.focusDefault));updateTimerUI()}persist()});$('soundVolumeInput').addEventListener('input',e=>{$('soundVolumeValue').textContent=`${e.target.value}%`;state.soundVolume=Number(e.target.value)/100;savePreferences()});$('soundVolumeInput').addEventListener('change',persist);$('motionSelect').addEventListener('change',e=>{state.motionLevel=e.target.value;applyMotionPreference();persist()});$('loadDemoBtn').addEventListener('click',loadDemoQuests);$('resetDemoBtn').addEventListener('click',clearDemoQuests)}async function authAction(action){const status=$('authStatus'),buttons=[$('signInBtn'),$('signUpBtn')];if(!supabaseClient){const message=window.supabase?'Cloud client is not ready yet. Refresh in a moment.':'Supabase library did not load. Check internet access and reload; your local data is safe.';status.textContent=message;return toast(message,'error')}const email=$('authEmail').value.trim(),password=$('authPassword').value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<6){const message='Enter a valid email and a password with at least 6 characters.';status.textContent=message;return toast(message,'error')}buttons.forEach(b=>b.disabled=true);status.textContent=action==='signin'?'Signing in…':'Creating your account…';try{const result=action==='signin'?await supabaseClient.auth.signInWithPassword({email,password}):await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}});if(result.error)throw result.error;user=result.data.user;if(result.data.session){await loadCloud();openModalClose();toast(action==='signin'?'Signed in and syncing.':'Account created and syncing.')}else{status.textContent=`Account created for ${email}. Check your inbox (and spam folder) for the confirmation link, then return here to sign in.`;toast('Account created. Confirm your email, then sign in.')}}catch(error){const message=error?.message||'Sign-in could not be completed. Check your connection and Supabase Auth settings.';status.textContent=message;toast(message,'error')}finally{buttons.forEach(b=>b.disabled=false)}}
function installSocialAuthButtons(){const row=document.createElement('div');row.className='social-auth-row';row.innerHTML='<div class="social-auth-divider"><span>or continue with</span></div><div class="social-auth-buttons"><button class="secondary-btn social-auth-btn" data-provider="google" type="button"><i class="fa-brands fa-google" aria-hidden="true"></i>Google</button><button class="secondary-btn social-auth-btn" data-provider="github" type="button"><i class="fa-brands fa-github" aria-hidden="true"></i>GitHub</button><button class="secondary-btn social-auth-btn" data-provider="apple" type="button"><i class="fa-brands fa-apple" aria-hidden="true"></i>Apple</button></div>';const signOut=$('signOutBtn');signOut.parentNode.insertBefore(row,signOut);row.querySelectorAll('[data-provider]').forEach(button=>button.addEventListener('click',()=>socialAuthAction(button.dataset.provider)))}
async function socialAuthAction(provider){const status=$('authStatus');if(!supabaseClient){const message=cloudConfigured()?'Cloud client is not ready yet. Refresh in a moment.':'Add your Supabase URL and public anon key in script.js first.';status.textContent=message;return toast(message,'error')}if(!['google','github','apple'].includes(provider))return;const buttons=[...document.querySelectorAll('.social-auth-btn')];buttons.forEach(button=>button.disabled=true);status.textContent=`Connecting to ${provider[0].toUpperCase()+provider.slice(1)}…`;try{const {error}=await supabaseClient.auth.signInWithOAuth({provider,options:{redirectTo:location.origin+location.pathname}});if(error)throw error}catch(error){const message=error?.message||`${provider} sign-in could not start. Check whether this provider is enabled in Supabase.`;status.textContent=message;toast(message,'error');buttons.forEach(button=>button.disabled=false)}}async function loadCloud(){if(!user||!supabaseClient)return;syncStatus('pending','Loading cloud backup…');const {data,error}=await supabaseClient.from(PROFILE_TABLE).select('payload,updated_at').eq('user_id',user.id).maybeSingle();if(error){syncStatus('error','Cloud sync needs attention');return}if(!data){const {error:seedError}=await supabaseClient.from(PROFILE_TABLE).upsert({user_id:user.id,payload:state,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(seedError){syncStatus('error','Cloud sync needs attention');return}storageWrite('tasksphere.lastCloudAt',String(Date.now()));syncStatus('ready',`Synced · ${user.email}`);return}if(data?.payload&&data.updated_at&&new Date(data.updated_at)>new Date(Number(storageRead('tasksphere.lastCloudAt')||0))){state={...blankState(),...data.payload,...JSON.parse(storageRead(PREFS_KEY)||'{}')};storageWrite(STORAGE_KEY,JSON.stringify(state));storageWrite('tasksphere.lastCloudAt',String(new Date(data.updated_at).getTime()));render();toast('Latest cloud backup loaded.')}else if(data?.payload){await syncCloud()}syncStatus('ready',`Synced · ${user.email}`)}
async function syncCloud(){if(!user||!supabaseClient){syncStatus('ready',cloudConfigured()?'Local mode · sign in to sync':'Saved on this device');return}if(!navigator.onLine){syncStatus('pending','Offline · changes queued');return}syncStatus('pending','Syncing securely…');const queue=JSON.parse(storageRead(QUEUE_KEY)||'[]');const payload=queue.length?queue[queue.length-1].payload:state;const {error}=await supabaseClient.from(PROFILE_TABLE).upsert({user_id:user.id,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error){syncStatus('error','Cloud sync paused · local copy safe');return}storageDelete(QUEUE_KEY);storageWrite('tasksphere.lastCloudAt',String(Date.now()));syncStatus('ready',`Synced · ${user.email}`)}
function exportData(){const blob=new Blob([JSON.stringify({app:'TaskSphere',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`tasksphere-backup-${dayKey()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded.')}
async function importData(file){try{const parsed=JSON.parse(await file.text()),incoming=parsed.data||parsed;if(!Array.isArray(incoming.tasks)||!Number.isFinite(Number(incoming.xp)))throw Error('This file does not look like a TaskSphere backup.');if(!confirm('Replace this device’s TaskSphere data with the selected backup?'))return;state={...blankState(),...incoming};persist();render();toast('Backup restored.')}catch(e){toast(e.message||'Could not read this backup.','error')}}
}
async function shareProgress(){try{const {rank}=levelInfo(),done=state.tasks.filter(t=>t.completed).length;const summary=`✦ My TaskSphere progress\n${done} quests completed · ${state.xp} XP · Level ${rank.level} ${rank.name} · ${currentStreak()} day streak\nSmall steps, big momentum.`;const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=630;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');const grad=ctx.createLinearGradient(0,0,1200,630);grad.addColorStop(0,'#151321');grad.addColorStop(1,'#282044');ctx.fillStyle=grad;ctx.fillRect(0,0,1200,630);ctx.fillStyle='#a78bfa';ctx.beginPath();ctx.arc(1010,95,195,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.3;ctx.fillStyle='#d59bff';ctx.beginPath();ctx.arc(90,600,160,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#d4c7ff';ctx.font='700 28px Manrope, sans-serif';ctx.fillText('✦ TASKSPHERE',84,100);ctx.fillStyle='#f8f6ff';ctx.font='800 68px Manrope, sans-serif';ctx.fillText('Small steps,',84,225);ctx.fillText('big momentum.',84,305);ctx.fillStyle='#c6bed9';ctx.font='500 26px DM Sans, sans-serif';ctx.fillText(`${done} quests completed     ·     ${currentStreak()} day streak`,86,385);ctx.fillStyle='#fff';ctx.font='700 27px DM Sans, sans-serif';ctx.fillText(`${state.xp.toLocaleString()} XP`,86,470);ctx.fillStyle='#bdaaff';ctx.fillText(`LEVEL ${rank.level}  ·  ${rank.name.toUpperCase()}`,320,470);ctx.fillStyle='#9c96ae';ctx.font='500 20px DM Sans, sans-serif';ctx.fillText('My TaskSphere progress',86,555);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not render card');const file=new File([blob],`tasksphere-progress-${dayKey()}.png`,{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){try{await navigator.share({files:[file],title:'My TaskSphere progress',text:summary});return}catch(e){if(e.name==='AbortError')return}}const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);try{await navigator.clipboard.writeText(summary);toast('Progress card downloaded · summary copied too.')}catch{toast('Progress card downloaded.')}}catch{toast('Could not create a progress card.','error')}}
function openQuestLog(){const done=state.tasks.filter(t=>t.completed).sort((a,b)=>(b.completedAt||0)-(a.completedAt||0));const frag=document.createElement('div');frag.innerHTML='<div class="section-kicker">LOOK HOW FAR YOU HAVE COME</div><h2 id="modalTitle">Completed quest log</h2><p>Your finished quests, one small win at a time.</p>';if(!done.length){const p=document.createElement('p');p.textContent='No completed quests yet. Your first win is waiting.';frag.append(p)}done.slice(0,60).forEach(t=>{const row=document.createElement('div');row.className='log-row';const name=document.createElement('strong');name.textContent=t.text;const meta=document.createElement('span');meta.textContent=`${CATEGORIES[t.category]||t.category} · +${XP[t.priority]||10} XP`;row.append(name,meta);frag.append(row)});openModal(frag)}
function paletteActions(query=''){const q=query.toLowerCase();const actions=[{label:'Add a new quest',icon:'fa-plus',run:openQuickAdd},{label:'Start or pause focus timer',icon:'fa-play',run:startTimer},{label:'Open theme shop',icon:'fa-palette',run:showShop},{label:'Open account and sync settings',icon:'fa-cloud',run:showSettings},{label:'Export backup',icon:'fa-download',run:exportData},{label:'Show completed quest log',icon:'fa-scroll',run:openQuestLog},{label:'Share progress card',icon:'fa-share-nodes',run:()=>shareProgress()},...state.tasks.filter(t=>!t.completed).map(t=>({label:`Focus on: ${t.text}`,icon:'fa-bullseye',run:()=>{$('focusTask').value=t.id;$('focus').scrollIntoView({behavior:'smooth',block:'center'})}}))];const matches=value=>{const text=value.toLowerCase();if(!q)return true;try{if(new RegExp(q,'i').test(value))return true}catch{}let i=0;for(const ch of text)if(ch===q[i])i++;return i===q.length};return actions.filter(a=>matches(a.label))}
function drawPalette(){const results=paletteActions($('paletteInput').value),wrap=$('paletteResults');wrap.replaceChildren();paletteIndex=0;if(!results.length){wrap.innerHTML='<div class="palette-empty">No matching commands or quests.</div>';return}results.forEach((a,i)=>{const row=document.createElement('div');row.className=`palette-item ${i===0?'selected':''}`;row.innerHTML=`<i class="fa-solid ${a.icon}"></i><span>${escapeHtml(a.label)}</span>`;row.addEventListener('click',()=>{closePalette();a.run()});wrap.append(row)})}
function openPalette(){$('paletteBackdrop').hidden=false;$('paletteInput').value='';drawPalette();$('paletteInput').focus()}function closePalette(){$('paletteBackdrop').hidden=true}
function wire(){ $('taskForm').addEventListener('submit',e=>{e.preventDefault();createTask({text:$('taskInput').value,category:$('categorySelect').value,priority:$('prioritySelect').value,est:$('estTimeInput').value,due:$('dueDateInput').value,repeat:$('repeatSelect').value});e.target.reset();$('prioritySelect').value='medium';$('taskInput').focus()});const boardTabs=[...document.querySelectorAll('.board-tab')];boardTabs.forEach((b,i)=>{b.addEventListener('click',()=>{boardTabs.forEach(x=>{x.classList.remove('active');x.setAttribute('aria-selected','false');x.tabIndex=-1});b.classList.add('active');b.setAttribute('aria-selected','true');b.tabIndex=0;filter=b.dataset.filter;renderTasks()});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?boardTabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+boardTabs.length)%boardTabs.length;boardTabs[next].focus();boardTabs[next].click()})});$('searchInput').addEventListener('input',renderTasks);$('sortSelect').addEventListener('change',renderTasks);$('openShop').addEventListener('click',showShop);$('openShopMobile').addEventListener('click',showShop);$('activityMode').value=state.activityMode||'focus';$('activityMode').addEventListener('change',e=>{state.activityMode=e.target.value;const preset=({focus:25,study:25,reading:30,exercise:20,sports:45,creative:45,custom:25,writing:45,mindfulness:10,chores:20})[state.activityMode];if(!timerRunning&&state.focus.mode==='focus'&&preset){state.focus.minutes=preset;focusSeconds=preset*60;saveTimerSession('paused')}savePreferences();persist();updateTimerUI();playSfx('tap')});$('settingsBtn').addEventListener('click',showSettings);$('accountAvatar').addEventListener('click',showSettings);$('timerStart').addEventListener('click',startTimer);$('chimeToggle').addEventListener('click',toggleChime);$('awayChimeToggle').addEventListener('click',()=>{state.awayChime=!state.awayChime;const b=$('awayChimeToggle');b.setAttribute('aria-pressed',String(state.awayChime));b.querySelector('.option-state').textContent=state.awayChime?'On':'Off';persist();if(state.awayChime)playSfx('return')});$('immersiveToggle').addEventListener('click',toggleImmersive);$('timerReset').addEventListener('click',()=>{clearInterval(timerInterval);timerRunning=false;timerDeadline=0;saveTimerSession('done');focusSessionId='';state.focus={minutes:state.focusDefault||25,mode:'focus'};focusSeconds=(state.focusDefault||25)*60;document.querySelectorAll('.timer-presets button').forEach(x=>x.classList.toggle('selected',Number(x.dataset.minutes)===(state.focusDefault||25)));updateTimerUI();$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Start focus';persist()});document.querySelectorAll('.timer-presets button').forEach(b=>b.addEventListener('click',()=>setTimerMinutes(Number(b.dataset.minutes))));$('feedPet').addEventListener('click',feedPet);$('petAvatar').addEventListener('click',interactPet);$('petInteract').addEventListener('click',interactPet);$('claimBounty').addEventListener('click',claimBounty);$('monthToggle').addEventListener('click',()=>setAnalytics('month'));$('yearToggle').addEventListener('click',()=>setAnalytics('year'));$('shareBtn').addEventListener('click',shareProgress);$('exportBtn').addEventListener('click',exportData);$('soundToggle').addEventListener('click',toggleSound);$('quickAddBtn').addEventListener('click',openQuickAdd);$('quickAddFab').addEventListener('click',openQuickAdd);$('importFile').addEventListener('change',e=>{if(e.target.files[0])importData(e.target.files[0]);e.target.value=''});$('questLogBtn').addEventListener('click',openQuestLog);$('modalClose').addEventListener('click',openModalClose);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))openModalClose()});$('commandBtn').addEventListener('click',openPalette);$('paletteInput').addEventListener('input',drawPalette);$('paletteBackdrop').addEventListener('click',e=>{if(e.target===$('paletteBackdrop'))closePalette()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette()}if(e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&!/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)&&!e.target.isContentEditable&&!document.body.classList.contains('focus-immersive')){e.preventDefault();openQuickAdd()}if(e.key==='Escape'){if(document.body.classList.contains('focus-immersive'))toggleImmersive();closePalette();openModalClose()}if(e.key==='Enter'&&!$('paletteBackdrop').hidden){const a=paletteActions($('paletteInput').value)[paletteIndex];if(a){closePalette();a.run()}}if(!$('paletteBackdrop').hidden&&e.key==='ArrowDown'){e.preventDefault();const rows=[...document.querySelectorAll('.palette-item')];if(rows.length){paletteIndex=(paletteIndex+1)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===paletteIndex))}}if(!$('paletteBackdrop').hidden&&e.key==='ArrowUp'){e.preventDefault();const rows=[...document.querySelectorAll('.palette-item')];if(rows.length){paletteIndex=(paletteIndex-1+rows.length)%rows.length;rows.forEach((r,i)=>r.classList.toggle('selected',i===paletteIndex))}}});const navLinks=[...document.querySelectorAll('.side-nav [data-section]')];navLinks.forEach(a=>a.addEventListener('click',()=>{setActiveNav(a.dataset.section);playSfx('tap')}));if('IntersectionObserver'in window){const sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)setActiveNav(visible.target.dataset.page)},{rootMargin:'-24% 0px -64% 0px',threshold:[0,.1,.25,.45,.65]});document.querySelectorAll('.workspace-page').forEach(section=>sectionObserver.observe(section))}document.addEventListener('visibilitychange',()=>{if(document.hidden){if(timerRunning){sessionWrite('tasksphere.focus-hidden-at',String(Date.now()));if(state.awayChime)playSfx('away')}return}if(timerRunning){tickTimer();sessionDelete('tasksphere.focus-hidden-at');if(state.awayChime&&timerRunning)playSfx('return')}})}
function setActiveNav(section){const view={overview:'home',quests:'quests',focus:'focus',progress:'progress'}[section]||section;if(['home','quests','focus','progress','shop','account'].includes(view))activateWorkspaceTab(view,false)}
function setAnalytics(range){analyticsRange=range;$('monthToggle').classList.toggle('active',range==='month');$('yearToggle').classList.toggle('active',range==='year');$('heatmap').classList.toggle('year-view',range==='year');renderHeatmap()}
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY&&event.newValue){try{const incoming=JSON.parse(event.newValue);state=normalizeAppState(incoming);render();updateTimerUI()}catch{}return}if(event.key!==TIMER_SESSION_KEY)return;if(!event.newValue){clearInterval(timerInterval);timerRunning=false;timerDeadline=0;focusSessionId='';focusSeconds=(state.focus.minutes||state.focusDefault||25)*60;$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Start focus';updateTimerUI();return}try{const saved=JSON.parse(event.newValue);if(saved.id&&saved.id===focusSessionId&&saved.status==='running'&&timerRunning&&timerDeadline===Number(saved.deadline))return;focusSessionId=saved.id||'';state.focus={minutes:saved.minutes||25,mode:saved.mode==='break'?'break':'focus'};clearInterval(timerInterval);if(saved.status==='running'){timerRunning=true;timerDeadline=Number(saved.deadline);focusSeconds=Math.max(0,Math.ceil((timerDeadline-Date.now())/1000));lastChimeMinute=Math.ceil(focusSeconds/60);$('timerStart').innerHTML='<i class="fa-solid fa-pause"></i> Pause session';timerInterval=setInterval(tickTimer,250)}else{timerRunning=false;timerDeadline=0;focusSeconds=Math.max(0,Number(saved.remaining)||0);$('timerStart').innerHTML='<i class="fa-solid fa-play"></i> Resume focus'}updateTimerUI()}catch{}});
function registerOfflineApp(){if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
function init(){applyDailyRules();restoreTimerSession();wire();$('upcomingViewAll').addEventListener('click',()=>{activateWorkspaceTab('quests');$('quests').scrollIntoView({behavior:'smooth',block:'start'})});render();updateTimerUI();maybeWelcome();if(new URLSearchParams(location.search).get('action')==='quick-add')openQuickAdd();if(timerRunning){$('timerStart').innerHTML='<i class="fa-solid fa-pause"></i> Pause session';timerInterval=setInterval(tickTimer,250);tickTimer()}else if(expiredTimerSession){completeFocus()}registerOfflineApp();initCloud();window.addEventListener('online',()=>syncCloud());window.addEventListener('beforeunload',()=>{if(user)navigator.sendBeacon?.(`${SUPABASE_URL}/rest/v1/tasksphere_profiles`,'')});}
