var SAFE_MODES={cyber:'Cyber / Obsidian',zen:'Zen / Botanical',retro:'Synthwave Retro',brutalist:'Brutalist Architect'};
var uiAudio=null,audioUnlocked=false,ambientNode=null,pointerDrag=null,modalReturnFocus=null;
function storageRead(key,fallback=null){try{const value=window.localStorage.getItem(key);return value===null?fallback:value}catch{return fallback}}
function storageWrite(key,value){try{window.localStorage.setItem(key,value);return true}catch{return false}}
function storageDelete(key){try{window.localStorage.removeItem(key)}catch{}}
function sessionRead(key,fallback=null){try{const value=window.sessionStorage.getItem(key);return value===null?fallback:value}catch{return fallback}}
function sessionWrite(key,value){try{window.sessionStorage.setItem(key,value)}catch{}}
function sessionDelete(key){try{window.sessionStorage.removeItem(key)}catch{}}
function uuid(){try{return crypto.randomUUID()}catch{return `ts-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`}}
function normalizeTasks(tasks){if(!Array.isArray(tasks))return [];const seen=new Set();return tasks.filter(t=>t&&typeof t==='object').slice(0,1000).map(t=>{let id=String(t.id||'');if(!id||seen.has(id))id=uuid();if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)){id=uuid();while(seen.has(id))id=uuid()}seen.add(id);const completed=!!t.completed;return {...t,id,text:String(t.text||'Untitled quest').slice(0,140),category:Object.hasOwn(CATEGORIES,t.category)?t.category:'life',priority:['low','medium','high','urgent'].includes(t.priority)?t.priority:'medium',status:completed?'done':t.status==='review'?'progress':['todo','progress'].includes(t.status)?t.status:'todo',tags:Array.isArray(t.tags)?t.tags.filter(x=>typeof x==='string').slice(0,12):[],created:Number.isFinite(Number(t.created))?Number(t.created):Date.now(),completedAt:completed&&Number.isFinite(Number(t.completedAt))?Number(t.completedAt):completed?Date.now():null,subtasks:Array.isArray(t.subtasks)?t.subtasks.filter(x=>x&&typeof x==='object').map(x=>({id:String(x.id||uuid()),text:String(x.text||'').slice(0,120),done:!!x.done})).slice(0,30):[]}})}
function normalizeAppState(raw={},prefs={}){if(!raw||typeof raw!=='object'||Array.isArray(raw))raw={};if(!prefs||typeof prefs!=='object'||Array.isArray(prefs))prefs={};const merged={...blankState(),...raw,...prefs};const num=(value,fallback,min=0,max=Number.MAX_SAFE_INTEGER)=>{const n=Number(value);return Number.isFinite(n)?Math.min(max,Math.max(min,n)):fallback};merged.version=2;merged.crtEnabled=typeof merged.crtEnabled==='boolean'?merged.crtEnabled:false;merged.tasks=normalizeTasks(raw.tasks);merged.xp=num(merged.xp,0);merged.gold=num(merged.gold,0);merged.petEnergy=num(merged.petEnergy,65,0,100);merged.bossHp=num(merged.bossHp,500,0,500);merged.focusMinutes=num(merged.focusMinutes,0);merged.soundVolume=num(merged.soundVolume,.45,0,1);merged.focusDefault=[10,15,20,25,30,45,60].includes(Number(merged.focusDefault))?Number(merged.focusDefault):25;merged.uiMode=Object.hasOwn({cyber:1,zen:1,retro:1,brutalist:1},merged.uiMode)?merged.uiMode:'cyber';merged.ambientSound=['off','white','rain','lofi'].includes(merged.ambientSound)?merged.ambientSound:'off';merged.focus=raw.focus&&typeof raw.focus==='object'&&!Array.isArray(raw.focus)?raw.focus:{minutes:merged.focusDefault,mode:'focus'};merged.focus={minutes:num(merged.focus.minutes,merged.focusDefault,1,180),mode:merged.focus.mode==='break'?'break':'focus'};merged.activityMode=['focus','study','reading','exercise','sports','creative','custom','writing','mindfulness','chores'].includes(merged.activityMode)?merged.activityMode:'focus';merged.theme=['default','cyberpunk','amoled','sunset'].includes(merged.theme)?merged.theme:'default';merged.motionLevel=['full','reduced'].includes(merged.motionLevel)?merged.motionLevel:'full';for(const key of ['soundEnabled','minuteChime','awayChime','streakShield'])merged[key]=typeof merged[key]==='boolean'?merged[key]:blankState()[key];merged.lastDecay=num(merged.lastDecay,Date.now(),0);merged.activity=raw.activity&&typeof raw.activity==='object'&&!Array.isArray(raw.activity)?Object.fromEntries(Object.entries(raw.activity).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)).map(([k,v])=>[k,num(v,0,0)])):{};merged.focusByDay=raw.focusByDay&&typeof raw.focusByDay==='object'&&!Array.isArray(raw.focusByDay)?Object.fromEntries(Object.entries(raw.focusByDay).filter(([k,v])=>/^\d{4}-\d{2}-\d{2}$/.test(k)).map(([k,v])=>[k,num(v,0,0)])):{};merged.shieldedDays=Array.isArray(raw.shieldedDays)?raw.shieldedDays.filter(v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)):[];merged.unlockedThemes=Array.isArray(raw.unlockedThemes)?[...new Set(raw.unlockedThemes.filter(v=>['default','cyberpunk','amoled','sunset'].includes(v)))]:['default'];if(!merged.unlockedThemes.includes('default'))merged.unlockedThemes.unshift('default');merged.bounties=raw.bounties&&typeof raw.bounties==='object'&&!Array.isArray(raw.bounties)?raw.bounties:{};merged.bossWeek=typeof merged.bossWeek==='string'?merged.bossWeek:'';merged.shieldUsedOn=typeof merged.shieldUsedOn==='string'?merged.shieldUsedOn:'';return merged}
function loadState(){let raw={},prefs={};try{raw=JSON.parse(storageRead(STORAGE_KEY,'{}'))||{}}catch{}try{prefs=JSON.parse(storageRead(PREFS_KEY,'{}'))||{}}catch{}return normalizeAppState(raw,prefs)}
function restoreTimerSession(){let saved=null;try{saved=JSON.parse(storageRead(TIMER_SESSION_KEY,'null'))}catch{}if(!saved||typeof saved!=='object'||Array.isArray(saved)){storageDelete(TIMER_SESSION_KEY);return}const minutes=Number(saved.minutes),remaining=Number(saved.remaining),deadline=Number(saved.deadline);if(!Number.isFinite(minutes)||minutes<1||minutes>180){storageDelete(TIMER_SESSION_KEY);return}restoredFocusTaskId=typeof saved.taskId==='string'?saved.taskId:'';focusSessionId=typeof saved.id==='string'?saved.id:'';state.focus={minutes,mode:saved.mode==='break'?'break':'focus'};if(saved.status==='running'&&Number.isFinite(deadline)&&deadline>0){timerDeadline=deadline;focusSeconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));lastChimeMinute=Math.ceil(focusSeconds/60);timerRunning=true;expiredTimerSession=focusSeconds===0}else{focusSeconds=Number.isFinite(remaining)?Math.max(0,Math.min(minutes*60,remaining)):minutes*60;timerRunning=false;timerDeadline=0}}
function preferencePayload(){return {soundVolume:state.soundVolume,soundEnabled:state.soundEnabled,minuteChime:state.minuteChime,awayChime:state.awayChime,motionLevel:state.motionLevel,focusDefault:state.focusDefault,activityMode:state.activityMode||'focus',uiMode:state.uiMode||'cyber',ambientSound:state.ambientSound||'off',crtEnabled:!!state.crtEnabled}}
function savePreferences(){storageWrite(PREFS_KEY,JSON.stringify(preferencePayload()));storageWrite(STORAGE_KEY,JSON.stringify(state))}
function persist(){const saved=storageWrite(STORAGE_KEY,JSON.stringify(state));storageWrite(PREFS_KEY,JSON.stringify(preferencePayload()));if(!saved){toast('Device storage is full or unavailable. Export a backup before continuing.','error');return}storageWrite(QUEUE_KEY,JSON.stringify([{queuedAt:Date.now(),payload:state}]));syncStatus('pending',navigator.onLine?'Saved on this device · syncing…':'Offline · changes queued');clearTimeout(syncTimer);syncTimer=setTimeout(()=>{try{syncCloud()}catch{}},450)}
function renderStats(){const tasks=state.tasks,done=tasks.filter(t=>t.completed).length,weekAgo=Date.now()-7*86400000,recent=tasks.filter(t=>t.completed&&Number(t.completedAt||0)>=weekAgo).length;$('statDone').textContent=done;$('statDoneFoot').textContent=done?`${done} quest${done===1?'':'s'} completed`:'Your first win is waiting';$('streakValue').textContent=currentStreak();$('statFocus').textContent=state.focusMinutes||0;$('statCompletion').textContent=tasks.length?Math.round(done/tasks.length*100):0;$('statVelocity').textContent=(recent/7).toFixed(recent%7===0?0:1);$('dateToday').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());$('todayLabel').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date())}
function renderTasks(){const list=$('questList'),oldRects=new Map([...list.querySelectorAll('.quest-item')].map(el=>[el.dataset.id,el.getBoundingClientRect()])),search=$('searchInput').value.trim().toLowerCase(),source=state.tasks.filter(t=>{if(filter==='active'&&(t.completed||t.status==='done'))return false;if(filter==='completed'&&!t.completed)return false;if(filter==='today'&&t.due!==dayKey()&&!(!t.due&&!t.completed))return false;if(search&&!`${t.text} ${CATEGORIES[t.category]||t.category} ${(t.tags||[]).join(' ')}`.toLowerCase().includes(search))return false;return true});const sort=$('sortSelect').value;if(sort==='due')source.sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));if(sort==='priority')source.sort((a,b)=>(XP[b.priority]||0)-(XP[a.priority]||0));if(sort==='created')source.sort((a,b)=>(b.created||0)-(a.created||0));list.replaceChildren();list.classList.add('kanban-board');const columns=[['todo','Backlog'],['progress','Active'],['done','Completed']];for(const [status,label] of columns){const col=document.createElement('section');col.className='kanban-column';col.dataset.status=status;const heading=document.createElement('div');heading.className='kanban-heading';heading.innerHTML=`<strong>${label}</strong><span>${source.filter(t=>(t.completed?'done':t.status||'todo')===status).length}</span>`;const zone=document.createElement('div');zone.className='kanban-dropzone';zone.dataset.status=status;zone.setAttribute('aria-label',`${label} drop zone`);zone.addEventListener('dragover',e=>{e.preventDefault();col.classList.add('drop-target')});zone.addEventListener('dragleave',e=>{if(!zone.contains(e.relatedTarget))col.classList.remove('drop-target')});zone.addEventListener('drop',e=>{e.preventDefault();col.classList.remove('drop-target');const id=dragId||pointerDrag?.id;if(id)moveTaskToStatus(id,status,e.target.closest('.quest-item')?.dataset.id)});for(const task of source.filter(t=>(t.completed?'done':t.status||'todo')===status)){const card=buildTask(task);if(!oldRects.has(String(task.id))){card.classList.add('quest-enter');card.style.setProperty('--entry-index',Math.min(source.indexOf(task),8))}card.draggable=true;card.addEventListener('dragstart',()=>{dragId=task.id;card.classList.add('dragging')});card.addEventListener('dragend',()=>{dragId=null;card.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'))});const statusPicker=document.createElement('select');statusPicker.className='status-picker';statusPicker.setAttribute('aria-label',`Move ${task.text} to a column`);[['todo','Backlog'],['progress','Active'],['done','Completed']].forEach(([value,label])=>{const option=document.createElement('option');option.value=value;option.textContent=label;option.selected=value===(task.completed?'done':task.status||'todo');statusPicker.append(option)});statusPicker.addEventListener('change',e=>{e.stopPropagation();moveTaskToStatus(task.id,statusPicker.value)});statusPicker.addEventListener('click',e=>e.stopPropagation());card.querySelector('.quest-actions')?.prepend(statusPicker);const handle=document.createElement('button');handle.type='button';handle.className='mini-action drag-handle';handle.title='Drag to move';handle.setAttribute('aria-label',`Move ${task.text}`);handle.innerHTML='<i class="fa-solid fa-grip-vertical"></i>';card.querySelector('.quest-actions')?.prepend(handle);card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();e.stopPropagation();const moving=dragId||pointerDrag?.id;if(moving&&moving!==task.id)moveTaskToStatus(moving,status,task.id);dragId=null});zone.append(card)}if(!zone.children.length){const empty=document.createElement('div');empty.className='kanban-empty';empty.textContent=status==='todo'?'Drop quests here':'Drop a quest here';zone.append(empty)}col.append(heading,zone);list.append(col)}$('emptyState').classList.toggle('show',source.length===0);$('questCount').textContent=state.tasks.filter(t=>!t.completed).length;$('countAll').textContent=state.tasks.length;$('countActive').textContent=state.tasks.filter(t=>!t.completed).length;$('countCompleted').textContent=state.tasks.filter(t=>t.completed).length;$('countToday').textContent=state.tasks.filter(t=>t.due===dayKey()&&!t.completed).length;requestAnimationFrame(()=>{if(shouldReduceMotion())return;for(const item of list.querySelectorAll('.quest-item')){const prev=oldRects.get(item.dataset.id);if(!prev||item.classList.contains('quest-enter'))continue;const next=item.getBoundingClientRect(),dx=prev.left-next.left,dy=prev.top-next.top;if(Math.abs(dx)+Math.abs(dy)>1)item.animate([{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:260,easing:'cubic-bezier(.22,1,.36,1)'})}})}
function moveTaskToStatus(id,status,beforeId){const task=state.tasks.find(t=>String(t.id)===String(id));if(!task)return;if(status==='done'&&!task.completed){toggleTask(task.id);return}if(status!=='done'&&task.completed){toggleTask(task.id);task.status=status}else task.status=status;if(beforeId&&String(beforeId)!==String(id))reorderTasks(id,beforeId);else{persist();render()}playSfx('move')}
function applyUIMode(mode,save=true){if(!Object.hasOwn(SAFE_MODES,mode))return;state.uiMode=mode;document.documentElement.dataset.mode=mode;if(document.body)document.body.dataset.theme=mode;document.documentElement.dataset.crt=String(!!state.crtEnabled);const colors={cyber:'#08090c',zen:'#faf8f5',retro:'#0d0221',brutalist:'#ffffff'};document.querySelector('meta[name="theme-color"]')?.setAttribute('content',colors[mode]);const btn=$('modeHubBtn');if(btn){btn.title=`Mode: ${SAFE_MODES[mode]} · Ctrl/Cmd+K`;btn.setAttribute('aria-label',`Current workspace mode: ${SAFE_MODES[mode]}`)}if(save)persist()}
function showModeHub(){const content=document.createElement('div');content.innerHTML='<div class="section-kicker">MODE HUB</div><h2 id="modalTitle">Choose your workspace mood</h2><p>Each mode reshapes the whole workspace. Your quests and reward shop stay yours.</p>';Object.entries(SAFE_MODES).forEach(([id,name])=>{const button=document.createElement('button');button.type='button';button.className=`mode-choice ${state.uiMode===id?'selected':''}`;button.dataset.mode=id;button.innerHTML=`<span class="mode-swatch mode-${id}"></span><span><strong>${name}</strong><small>${({cyber:'Focused contrast and electric accents',zen:'Warm paper, sage, and calmer motion',retro:'Neon colors and optional scanlines',brutalist:'Hard edges, high contrast, and strict grids'})[id]}</small></span>${state.uiMode===id?'<i class="fa-solid fa-check"></i>':''}`;button.addEventListener('click',()=>{applyUIMode(id);openModalClose();toast(`${name} enabled.`)});content.append(button)});const audio=document.createElement('div');audio.className='ambient-picker';audio.innerHTML='<div class="section-kicker">AMBIENT FOCUS SOUND</div><p>Generated in your browser. Sound starts after your first interaction and stops when you leave.</p><div class="ambient-options"><button type="button" data-ambient="off">Off</button><button type="button" data-ambient="white">White noise</button><button type="button" data-ambient="rain">Rain</button><button type="button" data-ambient="lofi">Lo-fi</button></div>';audio.querySelectorAll('[data-ambient]').forEach(b=>{b.classList.toggle('selected',(state.ambientSound||'off')===b.dataset.ambient);b.addEventListener('click',()=>setAmbientSound(b.dataset.ambient))});const crt=document.createElement('button');crt.type='button';crt.className='crt-toggle';crt.setAttribute('aria-pressed',String(!!state.crtEnabled));crt.textContent=`Retro CRT scanlines: ${state.crtEnabled?'On':'Off'}`;crt.addEventListener('click',()=>{state.crtEnabled=!state.crtEnabled;document.documentElement.dataset.crt=String(state.crtEnabled);crt.setAttribute('aria-pressed',String(state.crtEnabled));crt.textContent=`Retro CRT scanlines: ${state.crtEnabled?'On':'Off'}`;persist()});audio.append(crt);content.append(audio);openModal(content)}
function unlockAudio(){if(audioUnlocked)return;audioUnlocked=true;try{const C=window.AudioContext||window.webkitAudioContext;if(C){uiAudio=new C();if(uiAudio.state==='suspended')uiAudio.resume().catch(()=>{})}}catch{uiAudio=null}}
function playSfx(kind='success'){const volume=Math.max(0,Math.min(1,Number(state.soundVolume)||0));if((kind==='success'||kind==='move')&&navigator.vibrate)try{navigator.vibrate(kind==='move'?10:18)}catch{}if(state.soundEnabled===false||volume===0||!uiAudio||uiAudio.state!=='running')return;try{const now=uiAudio.currentTime,mode=state.uiMode||'cyber',base=mode==='zen'?330:mode==='retro'?660:mode==='brutalist'?180:440,tones=kind==='error'?[base*.55,base*.42]:kind==='move'?[base*.8,base*1.1]:kind==='success'||kind==='mode'?[base,base*1.25]:[base];tones.forEach((freq,i)=>{const osc=uiAudio.createOscillator(),gain=uiAudio.createGain();osc.type=mode==='brutalist'?'square':mode==='zen'?'sine':'triangle';osc.frequency.setValueAtTime(freq,now+i*.045);gain.gain.setValueAtTime(.0001,now+i*.045);gain.gain.exponentialRampToValueAtTime(.035*volume,now+i*.045+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.045+.12);osc.connect(gain);gain.connect(uiAudio.destination);osc.start(now+i*.045);osc.stop(now+i*.045+.13)})}catch{}}
function setAmbientSound(type){state.ambientSound=type;stopAmbient();if(type!=='off'&&Number(state.soundVolume)>0&&audioUnlocked&&uiAudio){try{if(type==='white'||type==='rain'){const buffer=uiAudio.createBuffer(1,uiAudio.sampleRate*2,uiAudio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const source=uiAudio.createBufferSource(),filterNode=uiAudio.createBiquadFilter(),gain=uiAudio.createGain();source.buffer=buffer;source.loop=true;filterNode.type='lowpass';filterNode.frequency.value=type==='rain'?850:1500;gain.gain.value=Math.max(0,(Number(state.soundVolume)||0)*.035);source.connect(filterNode);filterNode.connect(gain);gain.connect(uiAudio.destination);source.start();ambientNode={source,gain}}else{const osc=uiAudio.createOscillator(),gain=uiAudio.createGain();osc.type='sine';osc.frequency.value=174;gain.gain.value=Math.max(0,(Number(state.soundVolume)||0)*.018);osc.connect(gain);gain.connect(uiAudio.destination);osc.start();ambientNode={source:osc,gain}}}catch{}}persist();document.querySelectorAll('[data-ambient]').forEach(b=>b.classList.toggle('selected',b.dataset.ambient===type))}
function stopAmbient(){if(!ambientNode)return;try{if(uiAudio)ambientNode.gain.gain.setTargetAtTime(0,uiAudio.currentTime,.04);ambientNode.source.stop((uiAudio?.currentTime||0)+.2)}catch{}ambientNode=null}
function openModal(content){modalReturnFocus=document.activeElement;$('modalContent').replaceChildren(content);$('modalBackdrop').hidden=false;document.body.classList.add('modal-open');setTimeout(()=>$('modalContent').querySelector('button,input,select,[tabindex="0"]')?.focus()||$('modalClose').focus(),0)}
function openModalClose(){if($('modalBackdrop').hidden)return;const title=$('modalContent').querySelector('#modalTitle')?.textContent||'';if(title.includes('Make your next step feel lighter'))storageWrite('tasksphere.welcome.v1','1');$('modalBackdrop').hidden=true;document.body.classList.toggle('modal-open',!$('paletteBackdrop').hidden);modalReturnFocus?.focus?.();modalReturnFocus=null}
function openPalette(){$('paletteBackdrop').hidden=false;$('paletteInput').value='';drawPalette();document.body.classList.add('modal-open');$('paletteInput').focus()}
function closePalette(){if($('paletteBackdrop').hidden)return;$('paletteBackdrop').hidden=true;document.body.classList.toggle('modal-open',!$('modalBackdrop').hidden);$('commandBtn').focus()}
function paletteActions(query=''){const q=query.toLowerCase(),actions=[{label:'Add a new quest',icon:'fa-plus',run:openQuickAdd},{label:'Start or pause focus timer',icon:'fa-play',run:startTimer},{label:'Open theme shop',icon:'fa-palette',run:showShop},{label:'Choose workspace mode',icon:'fa-wand-magic-sparkles',run:showModeHub},{label:'Open account and sync settings',icon:'fa-cloud',run:showSettings},{label:'Export backup',icon:'fa-download',run:exportData},{label:'Show completed quest log',icon:'fa-scroll',run:openQuestLog},{label:'Share progress card',icon:'fa-share-nodes',run:shareProgress},...Object.entries(SAFE_MODES).map(([id,label])=>({label:`Switch mode: ${label}`,icon:'fa-swatchbook',run:()=>applyUIMode(id)})),...['all','active','completed','today'].map(key=>({label:`Show ${key==='all'?'all':key} quests`,icon:'fa-filter',run:()=>{const tab=document.querySelector(`.board-tab[data-filter="${key}"]`);tab?.click();$('quests').scrollIntoView({behavior:'smooth',block:'start'})}})),...state.tasks.filter(t=>!t.completed).map(t=>({label:`Focus on: ${t.text}`,icon:'fa-bullseye',run:()=>{$('focusTask').value=t.id;$('focus').scrollIntoView({behavior:'smooth',block:'center'})}}))];return actions.filter(a=>a.label.toLowerCase().includes(q))}
function installEnhancements(){applyUIMode(state.uiMode||'cyber',false);$('modeHubBtn')?.addEventListener('click',showModeHub);document.addEventListener('pointerdown',unlockAudio,{once:true,capture:true});document.addEventListener('keydown',unlockAudio,{once:true,capture:true});document.addEventListener('pointermove',e=>{if(!matchMedia('(pointer:fine)').matches)return;const root=document.documentElement;root.style.setProperty('--cursor-x',`${e.clientX}px`);root.style.setProperty('--cursor-y',`${e.clientY}px`)},{passive:true});document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.drag-handle');if(!handle)return;const card=handle.closest('.quest-item');if(!card)return;pointerDrag={id:card.dataset.id,startX:e.clientX,startY:e.clientY,started:false,source:card};handle.setPointerCapture?.(e.pointerId)});document.addEventListener('pointermove',e=>{if(!pointerDrag)return;if(!pointerDrag.started&&Math.hypot(e.clientX-pointerDrag.startX,e.clientY-pointerDrag.startY)<7)return;pointerDrag.started=true;pointerDrag.source.classList.add('dragging');const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.kanban-column');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));target?.classList.add('drop-target')});document.addEventListener('pointerup',e=>{if(!pointerDrag)return;const drag=pointerDrag;pointerDrag=null;drag.source.classList.remove('dragging');const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.kanban-column');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));if(drag.started&&target)moveTaskToStatus(drag.id,target.dataset.status,document.elementFromPoint(e.clientX,e.clientY)?.closest('.quest-item')?.dataset.id)});document.addEventListener('keydown',e=>{const modalOpen=!$('modalBackdrop').hidden,paletteOpen=!$('paletteBackdrop').hidden;if(e.key==='Escape'){if(paletteOpen)closePalette();else if(modalOpen)openModalClose()}if(e.key==='Tab'&&(modalOpen||paletteOpen)){const box=paletteOpen?$('paletteBackdrop'):$('modalBackdrop'),items=[...box.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(x=>x.offsetParent!==null);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAmbient()});}
function celebrateModeBurst(){if(shouldReduceMotion())return;const palette={cyber:['#6366f1','#06b6d4','#b8a6ff'],zen:['#4a6b53','#b6c89d','#d7a88a'],retro:['#ff2a85','#00f0ff','#b76cff'],brutalist:['#111111','#f5f5f5','#888888']}[state.uiMode||'cyber'];const layer=document.createElement('div');layer.className='celebration-layer';for(let i=0;i<18;i++){const particle=document.createElement('i');particle.style.setProperty('--particle-x',`${(Math.random()-.5)*240}px`);particle.style.setProperty('--particle-y',`${-40-Math.random()*150}px`);particle.style.setProperty('--particle-color',palette[i%palette.length]);layer.append(particle)}document.body.append(layer);setTimeout(()=>layer.remove(),900)}
async function syncCloud(){if(!user||!supabaseClient){syncStatus('ready',cloudConfigured()?'Local mode · sign in to sync':'Saved on this device');return}if(!navigator.onLine){syncStatus('pending','Offline · changes queued');return}try{syncStatus('pending','Syncing securely…');let queue=[];try{queue=JSON.parse(storageRead(QUEUE_KEY,'[]'))}catch{}if(!Array.isArray(queue))queue=[];const payload=queue.length?queue[queue.length-1]?.payload:state;const {error}=await supabaseClient.from(PROFILE_TABLE).upsert({user_id:user.id,payload,updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error){syncStatus('error','Cloud sync paused · local copy safe');return}storageDelete(QUEUE_KEY);storageWrite('tasksphere.lastCloudAt',String(Date.now()));syncStatus('ready',`Synced · ${user.email||'your account'}`)}catch{syncStatus('error','Cloud sync paused · local copy safe')}}
async function loadCloud(){if(!user||!supabaseClient)return;try{syncStatus('pending','Loading cloud backup…');const {data,error}=await supabaseClient.from(PROFILE_TABLE).select('payload,updated_at').eq('user_id',user.id).maybeSingle();if(error){syncStatus('error','Cloud sync needs attention');return}if(!data){await syncCloud();return}const last=Number(storageRead('tasksphere.lastCloudAt','0'))||0;if(data.payload&&Date.parse(data.updated_at)>last){const incoming=data.payload&&typeof data.payload==='object'?data.payload:{};state=normalizeAppState(incoming,(()=>{try{return JSON.parse(storageRead(PREFS_KEY,'{}'))}catch{return {}}})());storageWrite(STORAGE_KEY,JSON.stringify(state));storageWrite('tasksphere.lastCloudAt',String(Date.parse(data.updated_at)));render();toast('Latest cloud backup loaded.')}else if(data.payload)await syncCloud();syncStatus('ready',`Synced · ${user.email||'your account'}`)}catch{syncStatus('error','Cloud sync needs attention')}}
async function importData(file){try{const parsed=JSON.parse(await file.text()),incoming=parsed.data||parsed;if(!Array.isArray(incoming.tasks)||!Number.isFinite(Number(incoming.xp)))throw Error('This file does not look like a TaskSphere backup.');if(!confirm('Replace this device’s TaskSphere data with the selected backup?'))return;state=normalizeAppState(incoming);persist();render();toast('Backup restored.')}catch(e){toast(e.message||'Could not read this backup.','error')}}

