const selectedTaskIds=new Set();let selectionMode=false;let installPromptEvent=null;
function parseTaskInput(raw){let text=String(raw||''),tags=[],priority=null,due=null;text=text.replace(/(^|\s)#([\w-]+)/g,(_m,space,tag)=>{tags.push(tag);return space}).replace(/(^|\s)!(urgent|critical|p0|high|medium|med|low|p[1-3])\b/ig,(_m,space,level)=>{const k=level.toLowerCase();priority=['urgent','critical','p0'].includes(k)?'urgent':['high','p1'].includes(k)?'high':['low','p3'].includes(k)?'low':'medium';return space});const now=new Date();for(const [re,offset]of [[/\btomorrow\b/i,1],[/\btoday\b/i,0],[/\bnext week\b/i,7]]){if(re.test(text)){const d=new Date(now);d.setDate(d.getDate()+offset);due=dayKey(d);text=text.replace(re,' ');break}}const weekday=/\bnext (monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i.exec(text);if(weekday){const names=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'],target=names.indexOf(weekday[1].toLowerCase()),d=new Date(now);let delta=(target-d.getDay()+7)%7;if(delta===0)delta=7;d.setDate(d.getDate()+delta);due=dayKey(d);text=text.replace(weekday[0],' ')}return{text:text.replace(/\s+/g,' ').trim(),tags:[...new Set(tags)].slice(0,12),priority,due}}
function createTask(data){const parsed=parseTaskInput(data.text),text=parsed.text;if(!text)return;const task={id:uuid(),text,category:data.category||'life',priority:parsed.priority||data.priority||'medium',est:data.est||null,due:parsed.due||data.due||null,repeat:data.repeat||'none',completed:false,status:'todo',tags:parsed.tags,subtasks:[],created:Date.now(),completedAt:null};state.tasks.unshift(task);persist();render();playSfx('add');toast(`Quest added${task.due?' · due '+dueDescription(task.due):''}${task.tags.length?' · '+task.tags.map(x=>'#'+x).join(' '):''}.`)}
const baseBuildTask=buildTask;buildTask=function(task){const card=baseBuildTask(task),select=document.createElement('input');select.type='checkbox';select.className='bulk-select';select.checked=selectedTaskIds.has(String(task.id));select.setAttribute('aria-label',`Select ${task.text} for bulk actions`);select.addEventListener('click',e=>e.stopPropagation());select.addEventListener('change',e=>{e.stopPropagation();select.checked?selectedTaskIds.add(String(task.id)):selectedTaskIds.delete(String(task.id));updateBulkBar()});card.prepend(select);if(task.tags?.length){const tags=document.createElement('span');tags.className='task-hashtags';tags.textContent=task.tags.map(x=>'#'+x).join(' ');card.querySelector('.quest-meta')?.append(tags)}if(task.subtasks?.length){const ratio=document.createElement('span');ratio.className='subtask-ratio';ratio.textContent=`${task.subtasks.filter(x=>x.done).length}/${task.subtasks.length} steps`;card.querySelector('.task-progress')?.after(ratio)}return card};
function updateBulkBar(){const bar=$('bulkBar');if(!bar)return;bar.hidden=!selectionMode;bar.querySelector('[data-selected-count]').textContent=`${selectedTaskIds.size} selected`;document.body.classList.toggle('selection-mode',selectionMode)}
function bulkMove(){const status=$('bulkMove').value;if(!status||!selectedTaskIds.size)return;for(const task of state.tasks.filter(t=>selectedTaskIds.has(String(t.id)))){const becomesDone=status==='done'&&!task.completed;if(becomesDone){task.completedAt=Date.now();task.completed=true;state.xp+=XP[task.priority]||15;state.activity[dayKey()]=(state.activity[dayKey()]||0)+1;state.bossHp=Math.max(0,state.bossHp-45)}else if(status!=='done'&&task.completed){task.completed=false;task.completedAt=null}task.status=status}selectedTaskIds.clear();persist();render();playSfx('move');toast('Selected quests moved.')}
