function exportMarkdown(){const done=state.tasks.filter(t=>t.completed),open=state.tasks.filter(t=>!t.completed),lines=['# TaskSphere Workspace — Executive Summary','',`Generated: ${new Date().toLocaleString()}`,'',`- Completion: ${state.tasks.length?Math.round(done.length/state.tasks.length*100):0}% (${done.length}/${state.tasks.length})`,`- Current streak: ${currentStreak()} days`,`- XP: ${state.xp}`,'','## Active quests',...(open.length?open.map(t=>`- [ ] **${t.text}** — ${t.priority} priority${t.due?' · due '+t.due:''}${t.tags?.length?' · '+t.tags.map(x=>'#'+x).join(' '):''}`):['- No active quests']),'','## Completed quests',...(done.length?done.map(t=>`- [x] ${t.text}`):['- No completed quests'])];downloadText(lines.join('\n'),`tasksphere-summary-${dayKey()}.md`,'text/markdown');toast('Executive summary exported.')}
