function showArchitecture(){const c=document.createElement('div');c.innerHTML='<div class="section-kicker">ABOUT THE WORKSPACE</div><h2 id="modalTitle">Engineered by Ekampreet Singh</h2><p>TaskSphere Enterprise v2.5 · A local-first productivity workspace.</p><div class="spec-grid"><article><strong>Architecture</strong><span>Vanilla ES2022+ micro-state machine · CSS token design system · defensive Web Storage persistence.</span></article><article><strong>Capabilities</strong><span>Offline-first task flows · keyboard command center · focus timer · responsive analytics.</span></article><article><strong>Data & sync</strong><span>Device storage works without an account. Optional Supabase sign-in and cloud sync require your project setup.</span></article></div><p class="architecture-note">Portfolio contact and project links can be added here by the workspace owner.</p>';openModal(c)}
