/* Tactile interaction layer: audio is unlocked only from an actual user gesture. */
function unlockAudio(){if(audioUnlocked)return;audioUnlocked=true;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioContext=audioContext||new C();uiAudio=audioContext;if(audioContext.state==='suspended')audioContext.resume().catch(()=>{})}catch{audioContext=null;uiAudio=null}}
function playSfx(kind='tap'){if(!audioUnlocked||state.soundEnabled===false||!audioContext||audioContext.state!=='running')return;const ctx=audioContext,now=ctx.currentTime,volume=Math.max(0,Math.min(1,Number(state.soundVolume)||0));if(!volume)return;const theme=state.uiMode||'cyber';const beep=(from,to,duration=.1,wave='sine',gain=.035,delay=0)=>{try{const osc=ctx.createOscillator(),amp=ctx.createGain(),start=now+delay;osc.type=wave;osc.frequency.setValueAtTime(from,start);if(to&&to!==from)osc.frequency.exponentialRampToValueAtTime(Math.max(1,to),start+duration);amp.gain.setValueAtTime(.0001,start);amp.gain.exponentialRampToValueAtTime(Math.max(.0001,gain*volume),start+.008);amp.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(amp);amp.connect(ctx.destination);osc.start(start);osc.stop(start+duration+.015)}catch{}};if(kind==='pickup'){beep(220,180,.085,'sine',.025);return}if(kind==='drop'||kind==='move'){beep(150,80,.12,'triangle',.045);return}if(kind==='tick'){beep(800,800,.03,'square',.019);return}if(kind==='add'){beep(523,523,.075,'sine',.035);beep(659,659,.11,'sine',.032,.075);return}if(kind==='delete'){beep(300,100,.18,'sine',.03);return}if(kind==='success'||kind==='done'){beep(523,523,.14,'sine',.035);beep(659,659,.16,'sine',.032,.09);beep(784,784,.21,'sine',.035,.18);return}if(kind==='palette-open'||kind==='palette-close'){try{const buffer=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.12),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),amp=ctx.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.setValueAtTime(kind==='palette-open'?1400:1100,now);amp.gain.setValueAtTime(.0001,now);amp.gain.exponentialRampToValueAtTime(.018*volume,now+.012);amp.gain.exponentialRampToValueAtTime(.0001,now+.12);source.connect(filter);filter.connect(amp);amp.connect(ctx.destination);source.start(now);source.stop(now+.13)}catch{}return}if(kind==='mode'||kind==='theme'){if(theme==='zen'){beep(420,405,.19,'sine',.036);beep(630,615,.24,'sine',.018,.015)}else if(theme==='retro'){beep(880,210,.12,'square',.035);beep(1175,440,.11,'square',.026,.075)}else if(theme==='brutalist'){beep(180,180,.022,'square',.04);beep(110,110,.018,'square',.025,.035)}else{beep(988,1318,.11,'sine',.028);beep(1568,1568,.075,'sine',.023,.07)}return}if(kind==='error'){beep(240,170,.16,'triangle',.035);return}if(kind==='tap'){beep(620,570,.045,'triangle',.015);return}beep(440,520,.08,'sine',.02)}
const previousOpenPalette=openPalette,previousClosePalette=closePalette;openPalette=function(){previousOpenPalette();playSfx('palette-open')};closePalette=function(){const wasOpen=!$('paletteBackdrop').hidden;previousClosePalette();if(wasOpen)playSfx('palette-close')};
const previousApplyMode=applyUIMode;applyUIMode=function(mode,save=true){const before=state.uiMode;previousApplyMode(mode,save);if(save&&before!==mode)playSfx('mode')};
function confettiForWin(id){try{if(window.confetti&&!shouldReduceMotion())window.confetti({particleCount:78,spread:64,startVelocity:32,origin:{y:.68},colors:(state.uiMode==='zen'?['#4a6b53','#b6c89d','#d7a88a']:state.uiMode==='retro'?['#ff2a85','#00f0ff','#b76cff']:state.uiMode==='brutalist'?['#111111','#f5f5f5','#777777']:['#6366f1','#06b6d4','#b8a6ff'])});requestAnimationFrame(()=>{const card=document.querySelector(`.quest-item[data-id="${CSS.escape(String(id))}"]`);if(card){card.classList.remove('celebrate-flash');void card.offsetWidth;card.classList.add('celebrate-flash');setTimeout(()=>card.classList.remove('celebrate-flash'),700)}})}catch{}}
const originalToggleTaskNow=toggleTaskNow;toggleTaskNow=function(id){const before=state.tasks.find(t=>String(t.id)===String(id)),wasDone=!!before?.completed;originalToggleTaskNow(id);const after=state.tasks.find(t=>String(t.id)===String(id));if(after&&!wasDone&&after.completed)confettiForWin(id)};
const originalToggleSubtask=toggleSubtask;toggleSubtask=function(taskId,subId){const task=state.tasks.find(t=>String(t.id)===String(taskId)),sub=task?.subtasks?.find(s=>String(s.id)===String(subId));const wasDone=!!sub?.done;originalToggleSubtask(taskId,subId);if(sub&&!wasDone&&task.subtasks.length&&task.subtasks.every(s=>s.done)){playSfx('success');confettiForWin(taskId)}else if(sub&&wasDone&&!sub.done)playSfx('tick')};
const originalDeleteTaskNow=deleteTaskNow;deleteTaskNow=function(id){playSfx('delete');originalDeleteTaskNow(id)};
const originalRenderStats=renderStats,counterAnimations=new WeakMap();renderStats=function(){originalRenderStats();for(const id of ['statDone','streakValue','statXp','statFocus','statCompletion','statVelocity']){const el=$(id);if(!el)continue;const target=parseFloat(el.textContent.replace(/[^0-9.-]/g,''));if(!Number.isFinite(target))continue;const from=Number(el.dataset.counterValue??0),end=target;el.dataset.counterValue=String(end);const pending=counterAnimations.get(el);if(pending)cancelAnimationFrame(pending);if(from===end){el.textContent=Number.isInteger(end)?String(end):end.toFixed(1);continue}const start=performance.now(),duration=360;const step=time=>{const t=Math.min(1,(time-start)/duration),eased=1-Math.pow(1-t,3),value=from+(end-from)*eased;el.textContent=Number.isInteger(end)?String(Math.round(value)):value.toFixed(1);if(t<1)counterAnimations.set(el,requestAnimationFrame(step));else counterAnimations.delete(el)};counterAnimations.set(el,requestAnimationFrame(step))}};
function installTactileInteractions(){document.addEventListener('pointerdown',e=>{if(e.target.closest('.drag-handle'))playSfx('pickup');const button=e.target.closest('button');if(button&&!button.matches('.drag-handle,.mode-choice,.quest-actions button,#commandBtn,#modeHubBtn,#soundToggle,.quest-check,.subtask input,.smart-views button,.mini-action'))playSfx('tap')},{capture:true});document.addEventListener('dragstart',e=>{if(e.target.closest('.quest-item')&&!e.target.closest('.drag-handle'))playSfx('pickup')},true);}

/* Focus the workspace into six clear, keyboard-accessible views. Existing
   panels are moved intact so all of their behavior and state stays connected. */
const WORKSPACE_VIEWS=[['home','Home','fa-house'],['quests','Quest board','fa-list-check'],['focus','Focus mode','fa-bullseye'],['progress','Progress','fa-chart-column'],['shop','Shop','fa-bag-shopping'],['account','Account & sync','fa-cloud']];
function activateWorkspaceTab(view,scroll=false){if(!WORKSPACE_VIEWS.some(([id])=>id===view))return;const links=[...document.querySelectorAll('.workspace-tabs [data-view]')];links.forEach(link=>{const active=link.dataset.view===view;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});const activeLink=links.find(link=>link.dataset.view===view),indicator=document.querySelector('.nav-indicator'),nav=document.querySelector('.workspace-tabs');if(activeLink&&indicator&&nav){const horizontal=window.matchMedia('(max-width: 760px)').matches;indicator.style.setProperty('--nav-offset',`${horizontal?activeLink.offsetLeft:activeLink.offsetTop}px`);indicator.style.setProperty('--nav-size',`${horizontal?activeLink.offsetWidth:activeLink.offsetHeight}px`);if(horizontal)activeLink.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})}const current=WORKSPACE_VIEWS.find(x=>x[0]===view);const crumb=document.querySelector('.breadcrumb strong');if(crumb&&current)crumb.textContent=current[1];const gold=document.getElementById('tabGold');if(gold)gold.textContent=String(state.gold||0);const theme=document.querySelector('.destination-meta span:last-child');if(theme)theme.innerHTML=`<i class="fa-solid fa-palette"></i> ${THEMES.find(t=>t.id===state.theme)?.name||'Current theme'}`;document.documentElement.dataset.workspaceView=view;if(scroll)document.getElementById(`view-${view}`)?.scrollIntoView({behavior:'smooth',block:'start'});}
function installWorkspaceTabs(){const main=document.querySelector('.main-content'),dashboard=main?.querySelector('.dashboard-grid'),nav=document.querySelector('.sidebar .side-nav');if(!main||!dashboard||!nav)return;const original=[...dashboard.querySelectorAll('.column-main > *, .column-side > *')];const by=(sel)=>original.find(el=>el.matches(sel));const home=document.createElement('section'),quests=document.createElement('section'),focus=document.createElement('section'),progress=document.createElement('section'),shop=document.createElement('section'),account=document.createElement('section');const pages=[['home',home],['quests',quests],['focus',focus],['progress',progress],['shop',shop],['account',account]];pages.forEach(([id,p])=>{p.className='workspace-page';p.dataset.page=id;p.id=`view-${id}`;p.setAttribute('role','region');p.setAttribute('aria-label',WORKSPACE_VIEWS.find(x=>x[0]===id)[1])});
  nav.classList.add('workspace-tabs');nav.setAttribute('aria-label','Workspace sections');nav.innerHTML=`<span class="nav-indicator" aria-hidden="true"></span>${WORKSPACE_VIEWS.map(([id,label,icon])=>`<a class="nav-item workspace-tab${id==='home'?' active':''}" href="#view-${id}" data-view="${id}" aria-label="${label}"><i class="fa-solid ${icon}" aria-hidden="true"></i><span>${label}</span></a>`).join('')}`;if(!document.getElementById('openShopMobile')){const legacyShop=document.createElement('button');legacyShop.type='button';legacyShop.id='openShopMobile';legacyShop.hidden=true;document.querySelector('.sidebar-bottom')?.append(legacyShop)}
  const intro=(eyebrow,title,copy)=>{const x=document.createElement('header');x.className='page-intro';x.innerHTML=`<div><div class="section-kicker">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>`;return x};
  home.append(document.getElementById('overview'),document.querySelector('.stat-grid'));const hg=document.createElement('div');hg.className='tab-layout home-layout';const homeMain=document.createElement('div'),homeSide=document.createElement('div');homeMain.className='tab-stack';homeSide.className='tab-stack';homeMain.append(by('.upcoming-panel'),by('.week-panel'));homeSide.append(by('.streak-shield'),by('.bounty-panel'),by('.companion-panel'));hg.append(homeMain,homeSide);home.append(hg);
  quests.append(intro('PLAN YOUR WORK','Quest board','Capture a task, set a priority, and move work forward.'));const qg=document.createElement('div');qg.className='tab-stack';qg.append(by('.quest-create'),by('.board-panel'));quests.append(qg);
  focus.append(intro('MAKE SPACE TO THINK','Focus mode','Choose a session, link a quest, and keep your attention on one thing.'));const fg=document.createElement('div');fg.className='tab-layout focus-layout';const fmain=document.createElement('div'),fside=document.createElement('div');fmain.className='tab-stack';fside.className='tab-stack';fmain.append(by('.focus-panel'));fside.append(by('.rank-panel'));fg.append(fmain,fside);focus.append(fg);
  progress.append(intro('SEE YOUR MOMENTUM','Progress','Review your consistency, weekly activity, and the challenges you have overcome.'));const pg=document.createElement('div');pg.className='tab-layout progress-layout';const pmain=document.createElement('div'),pside=document.createElement('div');pmain.className='tab-stack';pside.className='tab-stack';pmain.append(by('.analytics-panel'));pside.append(by('.boss-card'));pg.append(pmain,pside);progress.append(pg);
  shop.append(intro('REWARDS & PERSONALIZATION','Workspace shop','Use earned gold to unlock themes and companion supplies.'));const shopCard=document.createElement('article');shopCard.className='panel destination-card';shopCard.innerHTML=`<div class="destination-icon"><i class="fa-solid fa-swatchbook"></i></div><div class="destination-copy"><div class="section-kicker">YOUR WORKSPACE</div><h2>Make it yours</h2><p>Browse available themes, equip a look, or pick up something for your companion.</p><div class="destination-meta"><span><i class="fa-solid fa-coins"></i> <b id="tabGold">${state.gold||0}</b> gold</span><span><i class="fa-solid fa-palette"></i> ${THEMES.find(t=>t.id===state.theme)?.name||'Current theme'}</span></div></div><button type="button" class="primary-btn" id="tabOpenShop"><i class="fa-solid fa-arrow-up-right-from-square"></i> Browse shop</button>`;shop.append(shopCard);
  account.append(intro('PROFILE & CLOUD','Account & sync','Manage sign-in, preferences, backups, and optional cloud synchronization.'));const accountGrid=document.createElement('div');accountGrid.className='account-grid';accountGrid.innerHTML=`<article class="panel account-card"><div class="destination-icon"><i class="fa-solid fa-cloud"></i></div><div class="section-kicker">SYNC STATUS</div><h2>Local-first workspace</h2><p>Your quests are saved on this device. Optional Supabase sync becomes available after configuration and sign-in.</p><div class="sync-summary"><span class="sync-dot" id="tabSyncDot"></span><span id="tabSyncText">Checking connection…</span></div><button type="button" class="secondary-btn" id="tabOpenSettings"><i class="fa-solid fa-sliders"></i> Account & preferences</button></article><article class="panel account-card"><div class="destination-icon"><i class="fa-solid fa-box-archive"></i></div><div class="section-kicker">YOUR DATA</div><h2>Backups & reports</h2><p>Keep a portable copy of your workspace or share a clean progress summary.</p><div class="account-actions"><button type="button" class="secondary-btn" id="tabExportJson"><i class="fa-solid fa-download"></i> Export backup</button><button type="button" class="text-btn" id="tabExportMd"><i class="fa-solid fa-file-lines"></i> Export progress report</button></div></article>`;account.append(accountGrid);
  dashboard.remove();const footer=main.querySelector('.footer');pages.forEach(([,p])=>main.insertBefore(p,footer));nav.addEventListener('click',e=>{const a=e.target.closest('[data-view]');if(!a)return;e.preventDefault();activateWorkspaceTab(a.dataset.view,true);playSfx('tap')});document.getElementById('openShop').addEventListener('click',showShop);document.getElementById('settingsBtn').addEventListener('click',showSettings);document.getElementById('tabOpenShop').addEventListener('click',showShop);document.getElementById('tabOpenSettings').addEventListener('click',showSettings);document.getElementById('tabExportJson').addEventListener('click',exportData);document.getElementById('tabExportMd').addEventListener('click',exportMarkdown);const syncText=document.getElementById('syncLabel'),syncDot=document.getElementById('syncDot'),copySync=()=>{document.getElementById('tabSyncText').textContent=syncText?.textContent||'Saved on this device';document.getElementById('tabSyncDot').className=syncDot?.className||'sync-dot'};copySync();if(syncText)new MutationObserver(copySync).observe(syncText,{childList:true,subtree:true,characterData:true});activateWorkspaceTab('home');window.addEventListener('resize',()=>activateWorkspaceTab(document.documentElement.dataset.workspaceView||'home'));window.lucide?.createIcons?.();}

